using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text.Json.Serialization.Metadata;

// Set up options with a known type resolver (only Person is registered).
var options = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};

// ── 1. Strongly-typed metadata retrieval ──
// GetTypeInfo returns non-generic JsonTypeInfo; cast to JsonTypeInfo<T>.
JsonTypeInfo<Person> personInfo =
    (JsonTypeInfo<Person>)options.GetTypeInfo(typeof(Person));

Console.WriteLine($"Type:       {personInfo.Type.Name}");
Console.WriteLine($"Kind:       {personInfo.Kind}");
Console.WriteLine($"Properties: {string.Join(", ", personInfo.Properties.Select(p => p.Name))}");

// Round-trip with the typed metadata
var json = JsonSerializer.Serialize(new Person("Alice", 30), personInfo);
var back = JsonSerializer.Deserialize(json, personInfo)!;
Console.WriteLine($"Round-trip: {json} → {back}");

// ── 2. Probe without throwing (TryGetTypeInfo) ──
// Available since .NET 9 – returns false instead of throwing when
// the resolver doesn't know about the requested type.
if (options.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? found))
    Console.WriteLine($"\n✔ Metadata for Person found (Kind={found!.Kind})");
else
    Console.WriteLine("\n✘ No metadata for Person");

if (options.TryGetTypeInfo(typeof(Uri), out _))
    Console.WriteLine("✔ Metadata for Uri found");
else
    Console.WriteLine("✘ No metadata for Uri (resolver doesn't cover it)");

// Show that the non-try path would throw for an uncovered type
// when the resolver is restrictive.
var strict = new JsonSerializerOptions
{
    TypeInfoResolver = JsonTypeInfoResolver.Combine() // empty resolver
};
strict.TryGetTypeInfo(typeof(int), out JsonTypeInfo? intInfo);
Console.WriteLine($"\nEmpty resolver → TryGetTypeInfo(int): {(intInfo is null ? "null (no throw!)" : "found")}");

public record Person(string Name, int Age);

